$risk_warning_ai_3 = "<strong>Elastyczne ustawienia i pełna kontrola:</strong> W dowolnej chwili dopasuj parametry ryzyka. Przejrzyście śledź w panelu wszystkie salda i operacje handlowe bez ukrytych opłat i ograniczeń dla wypłat.";
$risk_warning_disclaimer = "<strong>Ostrzeżenie:</strong> Handel zawsze niesie ze sobą ryzyko. Systemy automatyczne (w tym AI) nie dają gwarancji zysku, mogą zawieść na skutek błędów oprogramowania lub niespodziewanych wydarzeń rynkowych, a ponadto wymagają monitorowania przez użytkownika. Wyniki osiągane w przeszłości nie dają pewności wyników przyszłych. Platforma ma wyłącznie charakter informacyjny i marketingowy i nie udziela porad finansowych.";
$risk_warning_s1_heading = "1. Ryzyko ogólne i ryzyko rynku kryptowalut";
$risk_warning_s1_intro = "Kryptowaluty są bardzo zmiennymi, spekulacyjnymi aktywami handlowanymi całą dobę z rynkami, które w wielu jurysdykcjach podlegają niewielkiemu nadzorowi regulacyjnemu.";
$risk_warning_s1_1 = "Ich wartości mogą ulegać gwałtownym wahaniom w krótkim czasie, potencjalnie doprowadzając do całkowitej utraty kapitału inwestycyjnego.";
$risk_warning_s1_2 = "Silny wpływ na ich wartość rynkową mogą mieć zmiany przepisów, rozwiązania techniczne, naruszenia zabezpieczeń lub zjawiska makroekonomiczne o szerszym zasięgu.";
$risk_warning_s1_3 = "Wartość niektórych aktywów może obniżyć się do zera. Należy inwestować wyłącznie pieniądze, na których ewentualną stratę możemy sobie pozwolić.";
$risk_warning_s2_heading = "2. Wykonywanie zleceń, płynność i dźwignia finansowa";
$risk_warning_s2_1 = "<strong>Zmienność rynków i płynność:</strong> Gwałtowne wahania cen (10–20% i więcej dziennie) czy niska płynność (w szczególności mniejszych walut) mogą skutkować opóźnieniami, awariami platform oraz problemami z realizacją (ang. slippage). W wyjątkowych okolicznościach zlecenia zapobiegające stratom nie dadzą gwarancji zatrzymania ewentualnych strat.";
$risk_warning_s2_2 = "<strong>Zagrożenia wynikające z wykorzystania dźwigni i depozytu zabezpieczającego:</strong> Zyski i straty osiągane przy użyciu produktów lewarowanych pomnażają się, dlatego możliwe jest, że strata przekroczy sumę wstępnego depozytu. Mniej więcej od 70 do 80 procent rachunków inwestorów indywidualnych ulega stratom w przypadku inwestowania w produkty lewarowane.";
$risk_warning_s3_heading = "3. Ryzyka techniczne, powiązane z cyberbezpieczeństwem oraz osobami trzecimi";
$risk_warning_s3_1 = "<strong>Kwestie techniczne:</strong> Handel internetowy zawsze pociąga za sobą ryzyko wystąpienia usterki internetu, problemów ze sprzętem/oprogramowaniem lub z brakiem dostępu do usług.";
$risk_warning_s3_2 = "<strong>Cyberbezpieczeństwo:</strong> Profile korzystające z kryptowalut nierzadko są przedmiotem złośliwego oprogramowania, hakerstwa czy wyłudzania informacji. Nie da się odwrócić transakcji, zatem naruszenie poświadczeń danych logowania z reguły prowadzi do trwałej straty.";
$risk_warning_s3_3 = "<strong>Zewnętrzne platformy internetowe:</strong> Niniejsza strona może kierować użytkowników na platformy osób trzecich. W żaden sposób nie kontrolujemy, nie promujemy i nie zapewniamy o bezpieczeństwie ani operacjach bądź wypłacalności tego typu platform. Zalecamy dokonanie we własnym zakresie szczegółowego sprawdzenia przed złożeniem depozytów na platformach zewnętrznych.";
$risk_warning_s4_heading = "4. Prawo, podatki i ostateczne zapisy";
$risk_warning_s4_1 = "<strong>Prawidłowości podatkowo-prawne:</strong> Podstawy regulacyjne mają zróżnicowany charakter i podlegają szybkim przemianom. Klienci ponoszą całkowitą odpowiedzialność względem tego, aby działania inwestycyjne przez nich dokonywane podlegały regulacjom prawa krajowego i żeby w pełni regulowali oni kwestie podatkowe.";
$risk_warning_s4_2 = "<strong>Brak obietnic osiągnięcia dochodu:</strong> Pojęcie obarczonego brakiem niebezpieczeństw (lub pozbawionego ryzyka) inwestowania na giełdzie walut cyfrowych nie ma zastosowania w rzeczywistości. Przykłady dotyczące efektywności bądź przewidywań zysku mają wymiar tylko i wyłącznie hipotetyczny.";
$risk_warning_s4_3 = "<strong>Prawidłowe dopasowanie:</strong> W razie nie do końca pełnego zaznajomienia się ze zjawiskami zagrożeń, bądź używania środków na wydatki niezbędne czy środków obcych z zapożyczeń radzi się stronić od tego rodzaju inwestowania walutami kryptograficznymi. Do podjęcia właściwej, uzasadnionej decyzji powinno się uprzednio ubiegać o doradztwo ze sprawdzonym pośrednikiem do doradzania finansowego.";
